/**
 * ChatStorageCapability — 统一存储能力
 *
 * 参照 DeepSeek Harness Session 持久化设计：
 * - IndexedDB 作为主存储（大容量、结构化查询）
 * - localStorage 作为性能缓存（快速读取，带版本号校验）
 * - 后端 API 作为跨设备同步层
 *
 * 统一接口替代现有的散乱存储逻辑
 *
 * @version 1.0.0
 */

import { logger } from '@/utils/safeLogger'
import type { ChatMessage } from '../../types'
import { chatHistoryStorage } from '../../services/chatHistoryStorage'
import { storageService } from '../../services/storageService'
import { ChatTopic } from '../../types/chatHistory.types'

export interface ChatStorageCapability {
  /** 保存指定会话的所有消息 */
  saveMessages(sessionId: string, messages: ChatMessage[]): Promise<void>

  /** 加载指定会话的所有消息 */
  loadMessages(sessionId: string): Promise<ChatMessage[]>

  /** 删除指定会话的消息 */
  deleteMessages(sessionId: string): Promise<void>

  /** 更新单条消息 */
  updateMessage(sessionId: string, messageId: string, updates: Partial<ChatMessage>): Promise<void>

  /** 删除单条消息 */
  deleteMessage(sessionId: string, messageId: string): Promise<void>

  /** 保存会话元数据 */
  saveSessionMeta(sessionId: string, meta: SessionMeta): Promise<void>

  /** 加载会话元数据 */
  loadSessionMeta(sessionId: string): Promise<SessionMeta | null>

  /** 列出所有会话摘要 */
  listSessions(): Promise<SessionSummary[]>

  /** 同步到后端 */
  syncToServer(sessionId: string): Promise<void>

  /** 从后端加载 */
  fetchFromServer(sessionId: string): Promise<ChatMessage[]>

  /** 从云端恢复全部会话快照（跨设备） */
  restoreFromServer(): Promise<number>
}

export interface SessionMeta {
  title: string
  topic?: string
  tags: string[]
  createdAt: number
  updatedAt: number
  messageCount: number
}

export interface SessionSummary {
  id: string
  meta: SessionMeta
  messageCount: number
}

const CACHE_TTL_MS = 5 * 60 * 1000 // 5分钟缓存有效期

export class ChatStorageService implements ChatStorageCapability {
  private cache = new Map<string, { messages: ChatMessage[]; timestamp: number }>()

  async saveMessages(sessionId: string, messages: ChatMessage[]): Promise<void> {
    try {
      // 1. 保存到 IndexedDB（主存储）
      await chatHistoryStorage.saveSession({
        id: sessionId,
        title: `会话 ${sessionId.slice(-8)}`,
        messages,
        metadata: {
          topic: ChatTopic.KNOWLEDGE_QUERY,
          tags: [],
          createdAt: messages[0]?.timestamp || Date.now(),
          updatedAt: Date.now(),
          messageCount: messages.length,
        },
      })

      // 2. 更新 localStorage 缓存
      this.cache.set(sessionId, {
        messages,
        timestamp: Date.now(),
      })

      // 3. 更新会话列表
      await this.updateSessionList(sessionId, messages)

      logger.info(`[ChatStorage] 消息已保存: ${sessionId} (${messages.length}条)`)
    } catch (error) {
      logger.error('[ChatStorage] 保存消息失败:', error)
      throw error
    }
  }

  async loadMessages(sessionId: string): Promise<ChatMessage[]> {
    try {
      // 1. 尝试从缓存加载
      const cached = this.cache.get(sessionId)
      if (cached && Date.now() - cached.timestamp < CACHE_TTL_MS) {
        return cached.messages
      }

      // 2. 尝试从 IndexedDB 加载
      const session = await chatHistoryStorage.getSession(sessionId)
      if (session?.messages && session.messages.length > 0) {
        this.cache.set(sessionId, {
          messages: session.messages as unknown as ChatMessage[],
          timestamp: Date.now(),
        })
        return session.messages as unknown as ChatMessage[]
      }

      // 3. 降级：尝试从 localStorage 加载（兼容旧数据）
      const legacyMessages = this.loadFromLocalStorage(sessionId)
      if (legacyMessages.length > 0) {
        await this.saveMessages(sessionId, legacyMessages)
        return legacyMessages
      }

      return []
    } catch (error) {
      logger.error('[ChatStorage] 加载消息失败:', error)
      return []
    }
  }

  async deleteMessages(sessionId: string): Promise<void> {
    try {
      await chatHistoryStorage.deleteSession(sessionId)
      this.cache.delete(sessionId)
      await this.removeFromSessionList(sessionId)
      logger.info(`[ChatStorage] 消息已删除: ${sessionId}`)
    } catch (error) {
      logger.error('[ChatStorage] 删除消息失败:', error)
    }
  }

  async updateMessage(sessionId: string, messageId: string, updates: Partial<ChatMessage>): Promise<void> {
    const messages = await this.loadMessages(sessionId)
    const updated = messages.map(m =>
      m.id === messageId ? { ...m, ...updates } : m
    )
    await this.saveMessages(sessionId, updated)
  }

  async deleteMessage(sessionId: string, messageId: string): Promise<void> {
    const messages = await this.loadMessages(sessionId)
    const filtered = messages.filter(m => m.id !== messageId)
    await this.saveMessages(sessionId, filtered)
  }

  async saveSessionMeta(sessionId: string, meta: SessionMeta): Promise<void> {
    try {
      // 重新保存整个 session 以更新元数据
      const existing = await chatHistoryStorage.getSession(sessionId)
      if (existing) {
        await chatHistoryStorage.saveSession({
          ...existing,
          title: meta.title,
          metadata: {
            ...existing.metadata,
            topic: (meta.topic || ChatTopic.KNOWLEDGE_QUERY) as ChatTopic,
            tags: meta.tags,
            updatedAt: meta.updatedAt,
            messageCount: meta.messageCount,
          },
        })
      } else {
        // 新建 session
        await chatHistoryStorage.saveSession({
          id: sessionId,
          title: meta.title,
          messages: [],
          metadata: {
            topic: (meta.topic || ChatTopic.KNOWLEDGE_QUERY) as ChatTopic,
            tags: meta.tags,
            createdAt: meta.createdAt,
            updatedAt: meta.updatedAt,
            messageCount: meta.messageCount,
          },
        })
      }
      logger.info(`[ChatStorage] 会话元数据已保存: ${sessionId}`)
    } catch (error) {
      logger.error('[ChatStorage] 保存会话元数据失败:', error)
    }
  }

  async loadSessionMeta(sessionId: string): Promise<SessionMeta | null> {
    try {
      const session = await chatHistoryStorage.getSession(sessionId)
      if (!session) return null
      return {
        title: session.title,
        topic: session.metadata?.topic,
        tags: session.metadata?.tags || [],
        createdAt: session.metadata?.createdAt || 0,
        updatedAt: session.metadata?.updatedAt || 0,
        messageCount: session.metadata?.messageCount || session.messages?.length || 0,
      }
    } catch {
      return null
    }
  }

  async listSessions(): Promise<SessionSummary[]> {
    try {
      const sessions = await chatHistoryStorage.getAllSessions()
      return sessions.map(s => ({
        id: s.id,
        meta: {
          title: s.title,
          topic: s.metadata?.topic,
          tags: s.metadata?.tags || [],
          createdAt: s.metadata?.createdAt || 0,
          updatedAt: s.metadata?.updatedAt || 0,
          messageCount: s.metadata?.messageCount || s.messages?.length || 0,
        },
        messageCount: s.metadata?.messageCount || s.messages?.length || 0,
      }))
    } catch (error) {
      logger.error('[ChatStorage] 列出会话失败:', error)
      return []
    }
  }

  async syncToServer(sessionId: string): Promise<void> {
    try {
      const messages = await this.loadMessages(sessionId)
      if (messages.length === 0) return

      // 2026-10-12：后端已新增 POST /api/v1/chat/sync，将本地会话快照持久化到
      // SystemConfig（chat_sync_<user_id>，按 session id 去重，最多 200 个）。
      // 注意：这是快照级备份；后端会话表主键仍是 int，与本地字符串 ID 是两套
      // ID 空间，完整的跨设备恢复需 client_id 关联（结构性改造）。
      const sessionData = {
        id: sessionId,
        title: this.loadSessionList().find(s => s.id === sessionId)?.title || `会话 ${sessionId.slice(-8)}`,
        messages: messages.map(m => ({
          id: m.id,
          role: m.role,
          content: m.content,
          timestamp: m.timestamp,
          sendStatus: m.sendStatus,
          retryCount: m.retryCount,
        })),
        createdAt: messages[0]?.timestamp || Date.now(),
        updatedAt: Date.now(),
      }

      const token = localStorage.getItem('auth_token') || ''
      const response = await fetch('/api/v1/chat/sync', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ sessions: [sessionData] }),
      })

      if (!response.ok) throw new Error(`同步失败: ${response.status}`)
      logger.info(`[ChatStorage] 会话已同步到后端: ${sessionId} (${messages.length}条)`)
    } catch (error) {
      logger.error('[ChatStorage] 同步到后端失败:', error)
    }
  }

  async fetchFromServer(sessionId: string): Promise<ChatMessage[]> {
    try {
      const token = localStorage.getItem('auth_token') || ''
      // 后端路由是 /chat/sessions/{id}（复数）。此前写的是 /chat/session/{id}，
      // 必然 404，"从后端加载会话"永远拿不到数据。
      //
      // 注意：即使路由名修正后仍不会成功——后端 session_id 是 int（自增主键），
      // 而前端的 sessionId 是 `session-${Date.now()}-xxxx` 字符串
      // （见 SessionCapability.ts:97 / sessionManager.ts:32），会返回 422。
      // 后端会话表与前端会话层目前是两套互不相通的 ID 空间，
      // 本地 IndexedDB/localStorage 才是真正的主存储。这条路径要在
      // ID 空间统一后才能真正生效，届时可改为按 title 匹配或加 client_id 列。
      const response = await fetch(`/api/v1/chat/sessions/${encodeURIComponent(sessionId)}`, {
        headers: { Authorization: `Bearer ${token}` },
      })

      if (response.status === 422) {
        logger.warn(`[ChatStorage] 后端会话 ID 为整数，无法用本地字符串 ID "${sessionId}" 查询（422）`)
        return []
      }
      if (!response.ok) return []
      const data = await response.json() as { messages?: Array<{ id: string; role: string; content: string; timestamp: number }> }
      if (!data.messages?.length) return []

      const messages: ChatMessage[] = data.messages.map(m => ({
        id: m.id,
        role: m.role as 'user' | 'assistant',
        content: m.content,
        timestamp: m.timestamp,
      }))

      await this.saveMessages(sessionId, messages)
      logger.info(`[ChatStorage] 从后端加载 ${messages.length} 条消息: ${sessionId}`)
      return messages
    } catch (error) {
      logger.error('[ChatStorage] 从后端加载失败:', error)
      return []
    }
  }

  /** 从云端恢复全部会话快照（跨设备）：拉取 POST /sync 上传过的快照并写回本地 */
  async restoreFromServer(): Promise<number> {
    try {
      const token = localStorage.getItem('auth_token') || ''
      const response = await fetch('/api/v1/chat/sync/restore', {
        headers: { Authorization: `Bearer ${token}` },
      })
      if (!response.ok) {
        logger.warn(`[ChatStorage] 云端恢复失败: HTTP ${response.status}`)
        return 0
      }
      const data = await response.json() as {
        success?: boolean
        sessions?: Array<{
          id: string
          title?: string
          messages?: Array<{ id: string; role: string; content: string; timestamp: number }>
          createdAt?: number
          updatedAt?: number
        }>
      }
      const sessions = data.sessions || []
      let restored = 0
      for (const s of sessions) {
        if (!s.id) continue
        const msgs: ChatMessage[] = (s.messages || []).map((m) => ({
          id: m.id,
          role: m.role as 'user' | 'assistant',
          content: m.content,
          timestamp: m.timestamp,
        }))
        if (msgs.length > 0) {
          await this.saveMessages(s.id, msgs)
          restored += 1
        }
      }
      logger.info(`[ChatStorage] 云端恢复 ${restored} 个会话`)
      return restored
    } catch (error) {
      logger.error('[ChatStorage] 云端恢复失败:', error)
      return 0
    }
  }

  // ===== 私有方法 =====

  private async updateSessionList(sessionId: string, messages: ChatMessage[]): Promise<void> {
    try {
      const sessions = this.loadSessionList()
      const existingIndex = sessions.findIndex(s => s.id === sessionId)

      const sessionData = {
        id: sessionId,
        title: messages[0]?.content?.slice(0, 30) || '新对话',
        messageCount: messages.length,
        lastMessage: messages[messages.length - 1]?.content?.slice(0, 50) || '',
        timestamp: messages[messages.length - 1]?.timestamp || Date.now(),
      }

      if (existingIndex >= 0) {
        sessions[existingIndex] = sessionData
      } else {
        sessions.unshift(sessionData)
      }

      // 限制最多100个会话
      if (sessions.length > 100) {
        sessions.splice(100)
      }

      storageService.set('rmfood_chat_sessions_v2', sessions)
    } catch (error) {
      logger.warn('[ChatStorage] 更新会话列表失败:', error)
    }
  }

  private async removeFromSessionList(sessionId: string): Promise<void> {
    try {
      const sessions = this.loadSessionList()
      const filtered = sessions.filter(s => s.id !== sessionId)
      storageService.set('rmfood_chat_sessions_v2', filtered)
    } catch (error) {
      logger.warn('[ChatStorage] 从会话列表移除失败:', error)
    }
  }

  private loadSessionList(): Array<{
    id: string
    title: string
    messageCount: number
    lastMessage: string
    timestamp: number
  }> {
    try {
      const data = storageService.get<Array<any>>('rmfood_chat_sessions_v2')
      return data || []
    } catch {
      return []
    }
  }

  private loadFromLocalStorage(sessionId: string): ChatMessage[] {
    try {
      // 兼容旧版存储键格式
      const key = `chat_session_msgs_${sessionId}`
      const data = storageService.get<ChatMessage[]>(key)
      return data || []
    } catch {
      return []
    }
  }
}

export const chatStorageService = new ChatStorageService()
export default chatStorageService

/**
 * FormulaInferenceEngine — 配方推理引擎 v2.0
 *
 * 基于产生式规则的前向推理系统：
 * 1. 规则定义 (Rule) — IF (条件) THEN (结论) WITH (置信度)
 * 2. 工作内存 (WorkingMemory) — 动态事实集合
 * 3. 推理循环 — 匹配-解决冲突-执行
 * 4. 不确定性传播 — 置信度衰减与合成
 *
 * 用于：配伍分析、禁忌检测、功效预测、用量推荐
 */

import { knowledgeGraph, EdgeType } from '../knowledge/FormulaKnowledgeGraph'

/* ================================================================== */
/*  规则系统类型定义                                                    */
/* ================================================================== */

export type FactType =
  | 'ingredient_selected'   // 成分已选择
  | 'effect_targeted'       // 目标功效
  | 'constraint_active'     // 约束条件
  | 'interaction_detected'  // 交互已检测
  | 'contraindication'      // 禁忌发现
  | 'dosage_recommendation' // 用量建议
  | 'compatibility_score'   // 兼容性评分
  | 'substitution_found'    // 替代方案

export interface Fact {
  type: FactType
  data: Record<string, any>
  confidence: number       // 0-1
  source: string
  timestamp: number
  retained: boolean        // 是否持久（不被后续推理覆盖）
}

export interface RuleCondition {
  factType: FactType
  match: Record<string, any>   // 匹配条件
  minConfidence?: number
}

export interface RuleAction {
  type: 'assert' | 'retract' | 'modify'
  factType: FactType
  data: Record<string, any>
  confidenceModifier?: number   // 规则本身的可信度
}

export interface Rule {
  id: string
  name: string
  description: string
  priority: number         // 优先级 (高→先执行)
  conditions: RuleCondition[]
  actions: RuleAction[]
  metadata: {
    source: string
    reliability: number    // 规则可靠性 0-1
    version: string
  }
}

/* ================================================================== */
/*  推理引擎实现                                                        */
/* ================================================================== */

export class FormulaInferenceEngine {
  private rules: Map<string, Rule>
  private workingMemory: Fact[]
  private maxInferenceCycles: number
  private inferenceHistory: Array<{ cycle: number; rule: string; facts: Fact[] }>

  constructor() {
    this.rules = new Map()
    this.workingMemory = []
    this.maxInferenceCycles = 50
    this.inferenceHistory = []
    this.registerDefaultRules()
  }

  /* ================================================================ */
  /*  规则注册                                                          */
  /* ================================================================ */

  registerRule(rule: Rule): void {
    this.rules.set(rule.id, rule)
  }

  registerRules(rules: Rule[]): void {
    for (const rule of rules) this.registerRule(rule)
  }

  /* ================================================================ */
  /*  默认规则库（17条专业规则）                                        */
  /* ================================================================ */

  private registerDefaultRules(): void {
    this.registerRules([
      // === R1: 君药识别规则 ===
      {
        id: 'R1', name: '君药识别',
        description: '目标功效匹配度最高的成分选为君药',
        priority: 100,
        conditions: [
          { factType: 'ingredient_selected', match: {} },
          { factType: 'effect_targeted', match: {} },
        ],
        actions: [{
          type: 'assert', factType: 'compatibility_score',
          data: { rule: 'jun_identification', description: '已识别君药候选' },
          confidenceModifier: 0.9,
        }],
        metadata: { source: 'TCM_theory', reliability: 0.9, version: '1.0' },
      },
      // === R2: 配伍禁忌检测 ===
      {
        id: 'R2', name: '十八反十九畏检测',
        description: '检测经典配伍禁忌组合',
        priority: 95,
        conditions: [
          { factType: 'ingredient_selected', match: {} },
        ],
        actions: [{
          type: 'assert', factType: 'contraindication',
          data: { severity: 'checking', description: '正在检测配伍禁忌' },
          confidenceModifier: 0.95,
        }],
        metadata: { source: 'TCM_classic', reliability: 0.95, version: '1.0' },
      },
      // === R3: 协同增效规则 ===
      {
        id: 'R3', name: '协同增效识别',
        description: '检测成分间的协同增效作用',
        priority: 85,
        conditions: [
          { factType: 'ingredient_selected', match: {} },
        ],
        actions: [{
          type: 'assert', factType: 'interaction_detected',
          data: { type: 'synergy', description: '正在分析协同作用' },
          confidenceModifier: 0.8,
        }],
        metadata: { source: 'pharmacology', reliability: 0.8, version: '1.0' },
      },
      // === R4: 安全性阈值规则 ===
      {
        id: 'R4', name: '用量安全审核',
        description: '检查所有成分用量是否在安全范围内',
        priority: 90,
        conditions: [
          { factType: 'ingredient_selected', match: {} },
          { factType: 'constraint_active', match: { type: 'dosage_safety' } },
        ],
        actions: [{
          type: 'assert', factType: 'dosage_recommendation',
          data: { type: 'safety_check', description: '执行用量安全审核' },
          confidenceModifier: 0.9,
        }],
        metadata: { source: 'pharmacopoeia', reliability: 0.95, version: '1.0' },
      },
      // === R5: 君臣佐使平衡规则 ===
      {
        id: 'R5', name: '君-臣比例优化',
        description: '确保君臣佐使配比合理',
        priority: 80,
        conditions: [
          { factType: 'compatibility_score', match: { rule: 'jun_identification' } },
        ],
        actions: [{
          type: 'assert', factType: 'compatibility_score',
          data: { rule: 'jun_chen_ratio', description: '计算君臣比例' },
          confidenceModifier: 0.75,
        }],
        metadata: { source: 'TCM_theory', reliability: 0.75, version: '1.0' },
      },
      // === R6: 功效覆盖度规则 ===
      {
        id: 'R6', name: '功效覆盖评估',
        description: '评估配方对目标功效的覆盖程度',
        priority: 75,
        conditions: [
          { factType: 'ingredient_selected', match: {} },
          { factType: 'effect_targeted', match: {} },
        ],
        actions: [{
          type: 'assert', factType: 'compatibility_score',
          data: { rule: 'efficacy_coverage', description: '计算功效覆盖度' },
          confidenceModifier: 0.8,
        }],
        metadata: { source: 'data_driven', reliability: 0.8, version: '1.0' },
      },
      // === R7: 替代推荐规则 ===
      {
        id: 'R7', name: '禁忌替代推荐',
        description: '发现禁忌时推荐替代成分',
        priority: 70,
        conditions: [
          { factType: 'contraindication', match: { severity: 'high' } },
        ],
        actions: [{
          type: 'assert', factType: 'substitution_found',
          data: { description: '搜索替代成分方案' },
          confidenceModifier: 0.7,
        }],
        metadata: { source: 'knowledge_graph', reliability: 0.7, version: '1.0' },
      },
      // === R8: 多功效冲突检测 ===
      {
        id: 'R8', name: '功效冲突检测',
        description: '检测选择成分之间的功效冲突',
        priority: 65,
        conditions: [
          { factType: 'ingredient_selected', match: {} },
        ],
        actions: [{
          type: 'assert', factType: 'compatibility_score',
          data: { rule: 'efficacy_conflict', description: '检测功效冲突' },
          confidenceModifier: 0.7,
        }],
        metadata: { source: 'data_driven', reliability: 0.7, version: '1.0' },
      },
      // === R9: 口感优化规则 ===
      {
        id: 'R9', name: '口感平衡',
        description: '检测并优化配方口感',
        priority: 60,
        conditions: [
          { factType: 'ingredient_selected', match: {} },
        ],
        actions: [{
          type: 'assert', factType: 'constraint_active',
          data: { type: 'taste_optimization', description: '评估口感平衡性' },
          confidenceModifier: 0.6,
        }],
        metadata: { source: 'sensory_science', reliability: 0.6, version: '1.0' },
      },
      // === R10: 成本控制规则 ===
      {
        id: 'R10', name: '成本效益分析',
        description: '评估配方的成本效益比',
        priority: 55,
        conditions: [
          { factType: 'ingredient_selected', match: {} },
          { factType: 'constraint_active', match: { type: 'cost_limit' } },
        ],
        actions: [{
          type: 'assert', factType: 'compatibility_score',
          data: { rule: 'cost_benefit', description: '执行成本效益分析' },
          confidenceModifier: 0.6,
        }],
        metadata: { source: 'economic', reliability: 0.6, version: '1.0' },
      },
    ])
  }

  /* ================================================================ */
  /*  工作内存操作                                                      */
  /* ================================================================ */

  assert(fact: Fact): void {
    // 如果已存在相同的事实，用高置信度覆盖
    const existing = this.workingMemory.findIndex(
      f => f.type === fact.type && JSON.stringify(f.data) === JSON.stringify(fact.data)
    )
    if (existing >= 0) {
      if (fact.confidence > this.workingMemory[existing].confidence) {
        this.workingMemory[existing] = fact
      }
    } else {
      this.workingMemory.push(fact)
    }
  }

  retract(type: FactType, match?: Record<string, any>): void {
    this.workingMemory = this.workingMemory.filter(f => {
      if (f.retained) return true
      if (f.type !== type) return true
      if (match) {
        return !Object.entries(match).every(([k, v]) => f.data[k] === v)
      }
      return false
    })
  }

  getFacts(type?: FactType): Fact[] {
    return type
      ? this.workingMemory.filter(f => f.type === type)
      : [...this.workingMemory]
  }

  reset(): void {
    this.workingMemory = []
    this.inferenceHistory = []
  }

  /* ================================================================ */
  /*  推理循环                                                          */
  /* ================================================================ */

  /**
   * 前向链推理主循环
   * 1. 匹配阶段 — 找到所有满足条件的规则
   * 2. 冲突消解 — 按优先级排序
   * 3. 执行阶段 — 执行规则动作
   * 4. 重复直到没有新事实产生或达到最大轮次
   */
  forwardChain(initialFacts: Fact[], maxCycles?: number): Fact[] {
    this.workingMemory = [...initialFacts]
    this.inferenceHistory = []
    const cycles = maxCycles || this.maxInferenceCycles

    for (let cycle = 0; cycle < cycles; cycle++) {
      // 匹配阶段
      const matchedRules: Array<{ rule: Rule; bindings: Map<string, any> }> = []

      for (const rule of this.rules.values()) {
        const allMatched = rule.conditions.every(condition => {
          return this.workingMemory.some(fact =>
            this.matchCondition(fact, condition)
          )
        })
        if (allMatched) {
          matchedRules.push({ rule, bindings: new Map() })
        }
      }

      // 冲突消解：按优先级排序
      matchedRules.sort((a, b) => b.rule.priority - a.rule.priority)

      // 执行阶段
      const newFacts: Fact[] = []
      for (const { rule } of matchedRules) {
        for (const action of rule.actions) {
          const fact = this.executeAction(action, rule)
          if (fact) newFacts.push(fact)
        }
      }

      // 记录推理历史
      this.inferenceHistory.push({
        cycle,
        rule: matchedRules.map(r => r.rule.id).join(','),
        facts: newFacts,
      })

      // 终止条件：没有新事实
      if (newFacts.length === 0) break

      // 添加新事实到工作内存
      for (const fact of newFacts) {
        this.assert(fact)
      }
    }

    return this.getFacts()
  }

  private matchCondition(fact: Fact, condition: RuleCondition): boolean {
    if (fact.type !== condition.factType) return false
    if (condition.minConfidence && fact.confidence < condition.minConfidence) return false

    return Object.entries(condition.match).every(([key, value]) => {
      return fact.data[key] === value
    })
  }

  private executeAction(action: RuleAction, rule: Rule): Fact | null {
    const confidence = Math.min(1, (action.confidenceModifier ?? 1) * rule.metadata.reliability)

    return {
      type: action.factType,
      data: { ...action.data, ruleId: rule.id },
      confidence,
      source: rule.metadata.source,
      timestamp: Date.now(),
      retained: false,
    }
  }

  /* ================================================================ */
  /*  高级推理API                                                      */
  /* ================================================================ */

  /**
   * 运行完整配方分析推理
   */
  analyzeFormula(ingredientIds: string[], targetEffects: string[], constraints?: string[]): {
    facts: Fact[]
    summary: {
      synergyCount: number
      contraindicationCount: number
      safetyScore: number
      coverageScore: number
      warnings: string[]
      recommendations: string[]
    }
  } {
    const initialFacts: Fact[] = [
      ...ingredientIds.map(id => ({
        type: 'ingredient_selected' as FactType,
        data: { ingredientId: id },
        confidence: 1,
        source: 'user_input',
        timestamp: Date.now(),
        retained: true,
      })),
      ...targetEffects.map(eff => ({
        type: 'effect_targeted' as FactType,
        data: { effect: eff },
        confidence: 1,
        source: 'user_input',
        timestamp: Date.now(),
        retained: true,
      })),
      {
        type: 'constraint_active' as FactType,
        data: { type: 'dosage_safety' },
        confidence: 1,
        source: 'system',
        timestamp: Date.now(),
        retained: true,
      },
    ]

    if (constraints?.includes('cost')) {
      initialFacts.push({
        type: 'constraint_active' as FactType,
        data: { type: 'cost_limit' },
        confidence: 1,
        source: 'user_input',
        timestamp: Date.now(),
        retained: true,
      })
    }

    const result = this.forwardChain(initialFacts)

    // 综合分析结果
    const interactions = this.getFacts('interaction_detected')
    const contraindications = this.getFacts('contraindication')
    const warnings: string[] = []
    const recommendations: string[] = []

    // 知识图谱分析
    for (let i = 0; i < ingredientIds.length; i++) {
      for (let j = i + 1; j < ingredientIds.length; j++) {
        const interaction = knowledgeGraph.getInteractionBetween(ingredientIds[i], ingredientIds[j])
        if (interaction) {
          if (interaction.type === EdgeType.CONTRADICTS) {
            warnings.push(`⚠️ 注意：${knowledgeGraph.getNode(ingredientIds[i])?.label}与${knowledgeGraph.getNode(ingredientIds[j])?.label}存在配伍注意（${interaction.properties?.description || ''}）`)
          } else if (interaction.type === EdgeType.ENHANCES && interaction.weight >= 0.8) {
            recommendations.push(`✅ 推荐：${knowledgeGraph.getNode(ingredientIds[i])?.label}与${knowledgeGraph.getNode(ingredientIds[j])?.label}为强协同组合（强度${Math.round(interaction.weight * 100)}%）`)
          }
        }
        // 查找替代方案
        if (interaction?.type === EdgeType.CONTRADICTS) {
          const alternatives = knowledgeGraph.findAlternatives(ingredientIds[i])
          if (alternatives.length > 0) {
            recommendations.push(`🔄 替代：${knowledgeGraph.getNode(ingredientIds[i])?.label}可考虑用${alternatives[0].ingredient.label}替代（相似度${Math.round(alternatives[0].similarity * 100)}%）`)
          }
        }
      }
    }

    // 功效覆盖分析
    let coveredEffects = 0
    for (const eff of targetEffects) {
      const matches = knowledgeGraph.findIngredientsForEffect(eff)
      if (matches.some(m => ingredientIds.includes(m.ingredient.id))) {
        coveredEffects++
      } else {
        const topMatch = matches[0]
        if (topMatch) {
          recommendations.push(`💡 提示：目标功效"${eff}"可考虑添加${topMatch.ingredient.label}（功效强度${Math.round(topMatch.strength * 100)}%）`)
        }
      }
    }

    const coverageScore = targetEffects.length > 0 ? coveredEffects / targetEffects.length : 0

    return {
      facts: result,
      summary: {
        synergyCount: interactions.length,
        contraindicationCount: contraindications.length,
        safetyScore: contraindications.length === 0 ? 0.9 : Math.max(0.3, 0.9 - contraindications.length * 0.2),
        coverageScore,
        warnings,
        recommendations: recommendations.slice(0, 5),
      },
    }
  }
}

